-- CHM 101 Exam Sprint: import 240 curated MCQs into an empty private bank
-- Sources: supplied CHM 101 files plus clearly labelled General CHM 101 enrichment
-- The script creates a bank if none exists and refuses to overwrite existing questions.
BEGIN;

DO $import$
DECLARE
  v_set_id uuid;
  v_set_count integer;
  v_question jsonb;
  v_option jsonb;
BEGIN
  SELECT count(*) INTO v_set_count
  FROM public.study_quiz_sets
  WHERE upper(regexp_replace(coalesce(course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'CHM101'
    AND delivery_mode = 'mock_exam'
    AND exam_campaign_key = 'supplementary-2026';

  IF v_set_count = 0 THEN
    INSERT INTO public.study_quiz_sets
      (title, description, course_code, level, semester, difficulty, time_limit_minutes,
       questions_count, published, visibility, source, delivery_mode, exam_campaign_key,
       access_tier, exam_question_count, diagnostic_question_count, diagnostic_time_limit_minutes)
    VALUES
      ('CHM 101 Exam Sprint Mock',
       'Private CHM 101 bank covering supplied General Chemistry I materials and broader CHM 101 foundations.',
       'CHM 101', '100', 'first', 'hard', 40,
       0, false, 'private', 'exam_sprint', 'mock_exam', 'supplementary-2026',
       'plus_monthly', 40, 10, 10)
    RETURNING id INTO v_set_id;
  ELSIF v_set_count = 1 THEN
    SELECT id INTO v_set_id
    FROM public.study_quiz_sets
    WHERE upper(regexp_replace(coalesce(course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'CHM101'
      AND delivery_mode = 'mock_exam'
      AND exam_campaign_key = 'supplementary-2026'
    LIMIT 1;
  ELSE
    RAISE EXCEPTION 'More than one CHM 101 Exam Sprint bank exists. Keep one target bank before importing.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.study_quiz_questions
    WHERE coalesce(set_id, quiz_set_id) = v_set_id
  ) THEN
    RAISE EXCEPTION 'The CHM 101 target bank already contains questions. Import stopped to prevent duplicates.';
  END IF;

  FOR v_question IN
    SELECT value FROM jsonb_array_elements($chm101_questions$[{"id":"9973f661-6962-5a99-8ad8-9cc8be844534","position":0,"prompt":"In a chemical equation, where are the reactants normally written?","explanation":"Reactants are written to the left of the reaction arrow, while products are written to the right.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Chemical Equations and Reaction Types","fingerprint":"5308c56a2a4fce3a2fd62c0e3ea253b7b6377996db59fc3e81e0bd9ad967cd0a","studyRef":{"sourceLabel":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d6fd9183-1d2f-5697-9b7c-69f0f831dbdb","text":"On the left side of the arrow","isCorrect":true,"position":0},{"id":"bcd5bf88-b979-5d13-8236-9cf0d8c65baa","text":"On the right side of the arrow","isCorrect":false,"position":1},{"id":"1037149f-85cb-5c82-9eb5-2d81841114af","text":"Above the reaction arrow only","isCorrect":false,"position":2},{"id":"f81a94e0-a235-5136-8cb2-412578135987","text":"Below the products","isCorrect":false,"position":3}]},{"id":"c7090bc4-98e9-5ee0-814f-de47b1f8029b","position":1,"prompt":"What does a coefficient placed before a chemical formula represent?","explanation":"A coefficient gives the relative amount of a species without changing its chemical identity.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Chemical Equations and Reaction Types","fingerprint":"cdea908a5cc4a9a63ef766241eff7a7b1a9d4dd0763d40dd0bef6a983f9f6f55","studyRef":{"sourceLabel":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"Unit 5a; CHM 10