y":"easy","cognitive":"recall","topic":"Chemical Equations and Reaction Types","fingerprint":"2259ce58553c23add558f62986a7a778242180aa78282932c600194cc17c480f","studyRef":{"sourceLabel":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"15916842-2fb4-53ee-b7ce-8828c57e7d12","text":"(g)","isCorrect":false,"position":0},{"id":"f7e56fee-e8d8-5779-8f7b-4401c51ad2c4","text":"(aq)","isCorrect":true,"position":1},{"id":"55d2a464-40bd-5b7d-8216-42cd6cfe7640","text":"(s)","isCorrect":false,"position":2},{"id":"262a64c6-06e9-5c6f-aacb-3e9159cdf28f","text":"(l)","isCorrect":false,"position":3}]},{"id":"32e8d526-a882-5240-9e36-dde18523f20d","position":4,"prompt":"Why must a chemical equation be balanced?","explanation":"Atoms are rearranged in a reaction, not created or destroyed.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Chemical Equations and Reaction Types","fingerprint":"0c092033c4f97c168ad3f731d125594d44d34790a5bea2efd5e35dec99834ac6","studyRef":{"sourceLabel":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"Unit 5a; CHM 101 Chemical Equation & Stoichiometry slides","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"2e2a1109-613d-515b-8b81-9268b149fc04","text":"To obey conservation of atoms","isCorrect":true,"position":0},{"id":"edf72046-6361-599c-b366-08bf3a85cbd8","text":"To make every coefficient equal","isCorrect":false,"position":1},{"id":"2ddd4846-c77f-5fde-9b27-d1a48ac8c053","text":"To remove all products","isCorrect":false,"position":2},{"id":"d942de38-a9e4-5