pleted":true,"humanVerificationRequired":true},"options":[{"id":"bd77cfc4-32a4-5398-ac68-559674f8c5eb","text":"Pressure","isCorrect":false,"position":0},{"id":"d58d1620-95da-5a92-868f-d1ddcf47bb55","text":"Molar mass","isCorrect":false,"position":1},{"id":"fca760b0-8d0d-5103-a16d-53668849fa1d","text":"Density","isCorrect":false,"position":2},{"id":"cd07e238-7323-5b1b-ba26-03f2252e999f","text":"Absolute temperature","isCorrect":true,"position":3}]},{"id":"8a3e1ea9-f314-5903-a1b4-01542a875009","position":162,"prompt":"Avogadro's law states that equal gas volumes at the same temperature and pressure contain equal what?","explanation":"At fixed T and P, volume is proportional to amount in moles.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"f58d834a1516195acc5e03288f751bc2cc873c8b371d6f5a5fda6ae5ff04df97","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a2c6838e-5a69-5a19-80ca-b6299d66b8e3","text":"Densities","isCorrect":false,"position":0},{"id":"6b3d20fc-92f1-5310-ae93-2aa5945435d1","text":"Atomic numbers","isCorrect":false,"position":1},{"id":"1646fe78-ce3f-544b-a8f3-d4044ea7a1ed","text":"Numbers of molecules","isCorrect":true,"position":2},{"id":"4b88b72d-a243-5052-91cd-caa908e248ec","text":"Masses","isCorrect":false,"position":3}]},{"id":"49594366-305a-5586-be6c-845b8fdf4d8a","position":163,"prompt":"Which equation is the ideal-gas equation?","explanation":"The ideal-gas equation connects pressure, volume, amount and absolute temperature.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"b53d3584c94d6ec5685198d89b53601db4ba98002ec055f0a2230c410a3bff5a","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"12e9a12a-b79a-5cfb-a5bc-f96d7f533682","text":"PT = nR/V","isCorrect":false,"position":0},{"id":"d3c997ab-e267-5eb4-96c4-4fcce2d71d1f","text":"PV = nRT","isCorrect":true,"position":1},{"id":"23c3e3d4-23c8-560b-b77e-d0aa920e28b3","text":"P = nR/V T⁻¹","isCorrect":false,"position":2},{"id":"1c9c1116-614a-57e3-8ad9-07d4c2c8c31e","text":"V = PRnT","isCorrect":false,"position":3}]},{"id":"6e2d928a-f55c-5e46-8ccd-f835cb22dfdf","position":164,"prompt":"What temperature scale must normally be used in gas-law calculations?","explanation":"Gas-law proportionalities require absolute temperature.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"0f908a3636a377dae31aaffede256b0c12f0b544bad2d62cba38ea2a9854ee2b","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"c224d582-1604-53be-be65-c2933549d0be","text":"Kelvin","isCorrect":true,"position":0},{"id":"9bdfb3d4-9570-57e1-80b8-ffe88a46fc0e","text":"Celsius","isCorrect":false,"position":1},{"id":"fb64f641-289d-547a-8af1-3df3f02a55e3","text":"Fahrenheit","isCorrect":false,"position":2},{"id":"e829fd77-0137-5922-a17c-70c87a774c00","text":"Any scale without conversion","isCorrect":false,"position":3}]},{"id":"3aaa6b7b-8f15-5206-959c-eb720ff403d3","position":165,"prompt":"Dalton's law concerns what quantity in a gas mixture?","explanation":"Total pressure equals the sum of component partial pressures for an ideal mixture.