sition":1},{"id":"4f9750ab-6a4e-507c-9d91-47fc56c42d9a","text":"24.6 kPa","isCorrect":false,"position":2},{"id":"1e76950e-a0dc-5309-af97-cd78ea788f61","text":"831 kPa","isCorrect":false,"position":3}]},{"id":"e99bc2df-1ac3-56e1-b522-e07fe2b14182","position":169,"prompt":"A mixture contains gases at partial pressures 20, 35 and 45 kPa. What is the total pressure?","explanation":"Dalton's law gives 20 + 35 + 45 = 100 kPa.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"3583219e0218c77145abc48a49319fe988795b5c3af690f8d6879c27ba455cfd","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"c4c19d1b-f8be-542d-8ea2-b1bcffaf78ca","text":"45 kPa","isCorrect":false,"position":0},{"id":"936f677c-ebad-55df-892f-bbfecf842eaa","text":"65 kPa","isCorrect":false,"position":1},{"id":"18799633-1f2b-59b7-a7ba-f45611ae5807","text":"1575 kPa","isCorrect":false,"position":2},{"id":"0c5bd5ad-4a94-51aa-a4a4-db65b678fda1","text":"100 kPa","isCorrect":true,"position":3}]},{"id":"65511de9-1673-56a7-9eca-ba242f065bb2","position":170,"prompt":"According to Graham's law, which gas effuses faster?","explanation":"Effusion rate is inversely proportional to the square root of molar mass.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"b96ae772295ae6b00eaafd8894154ca622dd20402b457bab753da23f1ed77010","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d71d180e-7d13-5e99-9afe-c0e79e342661","text":"Both always effuse equally","isCorrect":false,"position":0},{"id":"4511049d-5ebd-52c2-8b57-576a0db94532","text":"Only a polar gas","isCorrect":false,"position":1},{"id":"fbe7e045-bb0f-505b-a324-5f094c0bf42f","text":"The gas with lower molar mass","isCorrect":true,"position":2},{"id":"788316b5-1a06-54ba-b450-a4fb83704073","text":"The gas with higher molar mass","isCorrect":false,"position":3}]},{"id":"8d93b92c-0722-58e1-919b-9b981d761963","position":171,"prompt":"Why do real gases deviate most from ideal behaviour at high pressure?","explanation":"Crowding makes finite molecular size and intermolecular interactions important.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"da8d554dfb9a9266621ee1d1eeedce0c059a8820e96b45bb701e1733491bbcc7","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"98087536-e25f-5a82-8cf9-c2ddc214291d","text":"Pressure stops being measurable","isCorrect":false,"position":0},{"id":"7bfc6a11-f079-58a4-8a2e-3f093961e0de","text":"Molecular volume and attractions become significant","isCorrect":true,"position":1},{"id":"31b3dac3-6d8a-53ed-9841-96367fb62d74","text":"Molecules lose all kinetic energy","isCorrect":false,"position":2},{"id":"45ab0ae2-10cf-58d1-842e-14adee662651","text":"The gas has no particles","isCorrect":false,"position":3}]},{"id":"017a1844-087d-5f68-840b-f523759a20a2","position":172,"prompt":"Under which conditions does a real gas behave most ideally?","explanation":"Particles are far apart and kinetic energy dominates attractions at low P and high T.","questionKind":"application","difficulty":"medium","cognitive":"application",