fbf-bd71-b443eeef813b","position":174,"prompt":"A gas occupies 5.0 L at 100 kPa and 300 K. What volume does it occupy at 150 kPa and 450 K?","explanation":"V₂ = V₁(P₁/P₂)(T₂/T₁) = 5(100/150)(450/300) = 5.0 L.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"0c05b0ff462f89226c22c970314b2e7a097250dae1bbc5106a800f1c36bc8f48","studyRef":{"sourceLabel":"KINETIC THEORY OF MATTER","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"KINETIC THEORY OF MATTER","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"110dec9b-5aa4-5543-a30b-f921712e6c6b","text":"3.33 L","isCorrect":false,"position":0},{"id":"5b69fade-be88-5102-8d61-511267533e18","text":"7.50 L","isCorrect":false,"position":1},{"id":"7700260d-4c36-5347-a622-d7821007c7c2","text":"5.0 L","isCorrect":true,"position":2},{"id":"4b3ba106-a97d-5766-bc16-1b1d9150496c","text":"2.22 L","isCorrect":false,"position":3}]},{"id":"377e3d81-cc16-51af-8733-864ba165947f","position":175,"prompt":"At standard conditions near 273 K and 1 atm, one mole of an ideal gas occupies approximately what volume?","explanation":"The commonly used molar volume at 0 °C and 1 atm is about 22.4 L/mol.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"820a1e104f6685ee17aa51b61f7d70463ff7918289cf0242186dec962146c752","studyRef":{"sourceLabel":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"5788635d-202d-5069-8cbb-a3b06bbc745a","text":"44.8 L","isCorrect":false,"position":0},{"id":"7db1fd05-ee36-5f2d-8c10-648797ec0a20","text":"22.4 L","isCorrect":true,"position":1},{"id":"aa4941b0-4d54-5c60-8ecc-f80a90795afa","text":"1.00 L","isCorrect":false,"position":2},{"id":"5b2ce89a-a42a-5de5-90fb-b5473c5ec6c7","text":"8.31 L","isCorrect":false,"position":3}]},{"id":"faa25632-208a-534f-b0c7-0c0dbd30c5b5","position":176,"prompt":"What is the mole fraction of a gas with partial pressure 30 kPa in a mixture at 120 kPa?","explanation":"For an ideal mixture, mole fraction equals partial pressure divided by total pressure: 30/120.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"cf407dd45f9990cdad0ebf8fe344a14e7e20c831a10132be0c0d6f0e78f179dc","studyRef":{"sourceLabel":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"ac9d48b1-6fcb-5078-b83f-c22ff9ab6a82","text":"0.25","isCorrect":true,"position":0},{"id":"7355276e-c232-588f-a1f6-d4822e922ca9","text":"0.30","isCorrect":false,"position":1},{"id":"39e1dd34-4f7d-559e-ad1b-b79e1adc1733","text":"0.40","isCorrect":false,"position":2},{"id":"4acf9990-59ad-5d50-a35b-dc5273c05783","text":"4.0","isCorrect":false,"position":3}]},{"id":"8edf7561-5106-545e-a537-3b6ffb6d6f2d","position":177,"prompt":"What is the density of CO₂ at 300 K and 100 kPa? Use M = 44.0 g mol⁻¹ and R = 8.314 kPa L mol⁻¹ K⁻¹.","explanation":"Density d = PM/RT = 100 × 44/(8.314 × 300) ≈ 1.76 g/L.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"58f74aafa1da0328367979bfebedb5decbb09a849f0b910d07bee0946ce99986","studyRef":{"sourceLabel":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"3569009c-d619-5028-a91f-bed26e7e4636","text":"0.57 g L⁻¹","isCorrect":false,"position":0},{"id":"79ab8cfe-15ec-50ab-b0ae-07a30c46bb13","text":"4.40 g L⁻¹","isCorrect":false,"position":1},{"id":"b9d79c10-44f0-5e1d-9a7c-3366d30acbd2","text":"17.6 g L⁻¹","isCorrect":false,"position":2},{"id":"1f9f7044-590a-5b31-b7cc-b29b59dd5f29","text":"About 1.76 g L⁻¹","isCorrect":true,"position":3}]},{"id":"f531f1df-79c5-548b-8f3a-21a3c12b4955","position":178,"prompt":"A 2.0 L vessel contains 0.10 mol gas at 27 °C. What pressure is predicted using R = 8.314 kPa L mol⁻¹ K⁻¹?","explanation":"Convert 27 °C to 300 K, then P = 0.10 × 8.314 × 300/2.0 ≈ 125 kPa.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"83f29ae62f349e6fb04617ea8882f30020a3f33f23a8cfc120567ccd6ea18027","studyRef":{"sourceLabel":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"49e3cd94-2069-57fb-ac25-61497e3b2116","text":"83.1 kPa","isCorrect":false,"position":0},{"id":"d75122c0-48b2-5e05-8dcc-a81064636345","text":"249 kPa","isCorrect":false,"position":1},{"id":"b67f93b9-2df4-5d1b-ac44-19b6650d23e9","text":"About 125 kPa","isCorrect":true,"position":2},{"id":"f4980fc6-ea39-550a-adbd-2262a0df388c","text":"12.5 kPa","isCorrect":false,"position":3}]},{"id":"0aa87049-b089-5190-b628-72450b9d712d","position":179,"prompt":"A gas takes 100 s to effuse. Under identical conditions another gas with four times the molar mass takes approximately how long?","explanation":"Rate falls by √4 = 2; time for the same amount therefore doubles.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Gas Laws and Ideal-Gas Behaviour","fingerprint":"69b862a04628cde88028f91cd703c6e10bf3b5e489b49fc56bb9747ebba4b8bf","studyRef":{"sourceLabel":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Gas Laws and Ideal-Gas Behaviour","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"3784c717-8132-5380-bcbe-ccc2d0605866","text":"400 s","isCorrect":false,"position":0},{"id":"b11b7f04-a75e-5510-8ed5-be4e5cbdf8a2","text":"200 s","isCorrect":true,"position":1},{"id":"5e0a25db-c0bd-5e58-8701-df4a01dcd3f2","text":"25 s","isCorrect":false,"position":2},{"id":"cb2100ae-634e-530c-bf45-153cc9a05f6a","text":"50 s","isCorrect":false,"position":3}]},{"id":"ac1d3f0f-75b7-5558-9dfb-1543d3a3c03e","position":180,"prompt":"What does thermochemistry study?","explanation":"Thermochemistry focuses on energy transferred as heat during chemical and physical changes.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Thermochemistry and Calorimetry","fingerprint":"e59e26c7751488c8adfcc08d6ae18352a60622dbda11dab5c43690f471df9dbf","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"c5b4a619-6a5a-549e-b8c9-5ce42ad4aa47","text":"Heat changes accompanying chemical and physical processes","isCorrect":true,"position":0},{"id":"f763a745-4afb-5083-a9c4-6662cdbbb2b2","text":"Only atomic masses","isCorrect":false,"position":1},{"id":"93c686af-33d1-56bb-8108-b37a70b2656f","text":"The naming of compounds only","isCorrect":false,"position":2},{"id":"6d90b691-f3fe-5605-b3a8-6f7a5124cd12","text":"Motion without energy changes","isCorrect":false,"position":3}]},{"id":"662cbc5b-8a4a-5762-87b6-3213c050562d","position":181,"prompt":"What is the system in a thermochemical investigation?","explanation":"The system is the selected reaction or process; everything else is the surroundings.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Thermochemistry and Calorimetry","fingerprint":"4250f66de083fe3f1760f6d013e5497846c9d12c07a131c43eb85de5d79b130a","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"10d408b5-f478-52d9-a21e-b037e68476bd","text":"Everything outside the experiment","isCorrect":false,"position":0},{"id":"949453e6-7690-5ab2-9c52-3281a3afdda4","text":"Only the thermometer","isCorrect":false,"position":1},{"id":"f4da3afa-0b16-5101-82bb-3392991fe4e5","text":"The laboratory building in every case","isCorrect":false,"position":2},{"id":"e5f2e584-fe84-5b57-a957-e7390e9e7eab","text":"The part of the universe being studied","isCorrect":true,"position":3}]},{"id":"ebbfd1d3-9a72-57f6-8173-2be87b54104d","position":182,"prompt":"What sign does ΔH have for an exothermic process?","explanation":"An exothermic system releases heat and loses enthalpy, so ΔH < 0.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Thermochemistry and Calorimetry","fingerprint":"e7d3cf6c29d120b8896205e9d28f5c6098a185a3c1f84bab3725ef43b5abde15","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"cad1a62a-d8f6-5802-9309-ce8b76a94979","text":"Always zero","isCorrect":false,"position":0},{"id":"fe38c833-c271-5bc8-930b-e36c92a1e2ef","text":"Undefined","isCorrect":false,"position":1},{"id":"c9929de4-8916-5523-a3da-0d80110d7bfa","text":"Negative","isCorrect":true,"position":2},{"id":"1e520e91-d288-5363-8b48-866932792ce7","text":"Positive","isCorrect":false,"position":3}]},{"id":"4be4fe12-478d-52aa-ae02-c71df1c4a0b7","position":183,"prompt":"What sign does ΔH have for an endothermic process?","explanation":"An endothermic system absorbs heat, so its enthalpy increases.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Thermochemistry and Calorimetry","fingerprint":"f97dd4fcf0f58801ef6d55c43e22a3af81be51562e2c8f4ebc9e9cbf7180dee7","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"83fed901-51d6-58c2-a29a-dc7849195d8e","text":"It must equal pressure","isCorrect":false,"position":0},{"id":"0687195a-58d1-53b2-b80b-df17bfd5f108","text":"Positive","isCorrect":true,"position":1},{"id":"f7db6c36-821f-5249-a8c8-d79b9400e9bc","text":"Negative","isCorrect":false,"position":2},{"id":"00df48c5-297b-5eee-82e9-a5c483cd98bc","text":"Always zero","isCorrect":false,"position":3}]},{"id":"db34772c-1932-5cab-9bb0-11c9e33c920b","position":184,"prompt":"Which equation calculates heat absorbed by a substance when no phase change occurs?","explanation":"Heat equals mass times specific heat capacity times temperature change.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Thermochemistry and Calorimetry","fingerprint":"5bc5d62e9834a19f1f0da31124f1dc5b61454caf0a15dbb6208f3836f7ef9646","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"b7327da0-f7b2-50aa-bd8c-23f2bb8e2398","text":"q = mcΔT","isCorrect":true,"position":0},{"id":"d414c935-2c6b-5b08-bd58-0bfaefb22f64","text":"q = m/cΔT","isCorrect":false,"position":1},{"id":"daf33be5-8d68-5eda-a031-2a8c6c4b90ba","text":"q = PV","isCorrect":false,"position":2},{"id":"5458bb3d-929a-55a1-8473-4ace9d1f7e68","text":"q = nRT²","isCorrect":false,"position":3}]},{"id":"b5370e76-28c9-554d-9438-ee807f66545b","position":185,"prompt":"What is specific heat capacity?","explanation":"Specific heat capacity relates heat input to mass and temperature rise.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Thermochemistry and Calorimetry","fingerprint":"278768c380872aa4c5a9283367420c2ff088659ccc21105aa74feb1307bf1ded","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"960ad8c2-b5eb-5266-8486-9bd914a41cd7","text":"Heat released by one mole during combustion","isCorrect":false,"position":0},{"id":"d89404d0-637d-5516-ad88-9448c75cb1be","text":"Mass per unit volume","isCorrect":false,"position":1},{"id":"2a755e08-af86-5a3b-9355-5465df5aa2bd","text":"Pressure per unit temperature","isCorrect":false,"position":2},{"id":"41f3fb70-b049-58db-adf7-ed5901c010c0","text":"Heat needed to raise unit mass by one degree","isCorrect":true,"position":3}]},{"id":"15e69f24-0293-530d-9269-c9d982707ce2","position":186,"prompt":"If a reaction mixture warms its surroundings, the reaction is most likely what?","explanation":"Heat released by the system raises the surroundings' temperature.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Thermochemistry and Calorimetry","fingerprint":"bdcf0e3985acd8c9cd0cdf06416d61b5084611f6dd546a1a698443a283877a28","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"11b560cb-02f1-5065-adda-2909b4e74fc6","text":"At absolute zero","isCorrect":false,"position":0},{"id":"aaa0d953-81bc-56e4-a2d8-c78620f449c1","text":"Necessarily nonspontaneous","isCorrect":false,"position":1},{"id":"871cfae9-116e-5f61-87ec-435deeaab574","text":"Exothermic","isCorrect":true,"position":2},{"id":"c703b28a-3ef8-5314-9cce-4f71c4c21247","text":"Endothermic","isCorrect":false,"position":3}]},{"id":"7937b077-f55f-5878-a45f-17cd98df7c47","position":187,"prompt":"How much heat raises 50.0 g of water by 10.0 °C? Use c = 4.18 J g⁻¹ °C⁻¹.","explanation":"q = 50.0 × 4.18 × 10.0 = 2090 J.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Thermochemistry and Calorimetry","fingerprint":"75098e1f5f045a195e93edc4746f32e4da2bce6f3ce196dd1e9b9edf3cf4fb03","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"6b698a3b-572f-5917-979b-ba61e4c7eacd","text":"4180 J","isCorrect":false,"position":0},{"id":"2fe60816-b405-5d1f-a2fd-003f1e8707dc","text":"2090 J","isCorrect":true,"position":1},{"id":"1d5ff94a-e433-52dc-aeb2-6738d64e2876","text":"20.9 J","isCorrect":false,"position":2},{"id":"9f4e0fb6-7254-5e13-8a33-bba3e4f6829d","text":"418 J","isCorrect":false,"position":3}]},{"id":"e1f2ac55-a2a9-5509-abd2-3a7dd129f91f","position":188,"prompt":"A 100 g metal absorbs 900 J and warms by 20 °C. What is its specific heat capacity?","explanation":"c = q/(mΔT) = 900/(100 × 20) = 0.45 J g⁻¹ °C⁻¹.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Thermochemistry and Calorimetry","fingerprint":"d4805dee4910718e4d11cb1513fac2cd5f9ca5580b705a218aa2e41219b5979e","studyRef":{"sourceLabel":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","sourceKind":"supplied_material","reviewedFromLocalFiles":true},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"THERMOCHEMISTRY; CHM 101 THERMOCHEMISTRY","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"26e83ae9-ea5a-5497-9ff4-d49577f3b3e1","text":"0.45 J g⁻¹ °C⁻¹","isCorrect":true,"position":0},{"id":"fdfabc3f-1d83-5fde-9b2d-f8500aa02edc","text":"0.022 J g⁻¹ °C⁻¹","isCorrect":false,"position":1},{"id":"de248ddf-ccf5-5565-9071-778df51c7ae7","text":"4.5 J g⁻¹ °C⁻¹","isCorrect":false,"position":2},{"id":"79789385-1014-56e1-9809-21c735f316b8","text":"180 J g⁻¹ °C⁻¹","isCorrect":false,"position":3}]},{"id":"faf1834f-0190-56e2-8867-aebd66a1830d","position":189,"prompt":"In an insulated calorimeter, heat lost by a hot object is related to heat gained by the cooler water how?","explanation":"Energy conservation gives qhot + qcold = 0 when other heat exchanges are negligible.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Thermochemistry and Calorimetry","fingerprint":"bab9b80a2a457abed0ebec90ab949b2ee6b3b642a41bf