 enrichment: Redox Reactions and Electrochemistry","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d76bad84-4579-50f2-aba4-847dd4458ab7","text":"Equal to its group number in every case","isCorrect":false,"position":0},{"id":"b6adbdbf-92e7-504d-b343-de31997711bf","text":"0","isCorrect":true,"position":1},{"id":"7dc5692e-4183-5d9b-86d1-5e4aad09169a","text":"+1","isCorrect":false,"position":2},{"id":"b45dcf35-0424-5ed6-9fac-0037379dfabd","text":"−1","isCorrect":false,"position":3}]},{"id":"a51ff47d-8a94-54eb-9616-fed002f80e8a","position":236,"prompt":"How many moles of electrons are transferred when 1 mol Al becomes Al³⁺?","explanation":"Each Al atom loses three electrons: Al → Al³⁺ + 3e⁻.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Redox Reactions and Electrochemistry","fingerprint":"97b0afe03a4280495f4a5b5e2de72bb99e7745d93b2f06eaa33b9fad61bab3d3","studyRef":{"sourceLabel":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"76cb7d08-c0fd-5c1f-a203-71c611917b5a","text":"3 mol","isCorrect":true,"position":0},{"id":"27d2072f-e011-5171-89bb-15a387b8bcff","text":"1 mol","isCorrect":false,"position":1},{"id":"915ae7e1-171c-52ac-b9aa-5250147bd1b3","text":"2 mol","isCorrect":false,"position":2},{"id":"d2582471-5d16-5377-bcb8-93612e87524c","text":"6 mol","isCorrect":false,"position":3}]},{"id":"ece62bcc-da65-5e7e-80a3-3a323bbc30d7","position":237,"prompt":"Which electrode is positive in a galvanic cell?","explanation":"The spontaneous reaction sends electrons away from the negative anode toward the positive cathode.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Redox Reactions and Electrochemistry","fingerprint":"c82ac3dce4396879873311f5cf173a4ade70ff00b09deab6688ef5be5e6ac1d2","studyRef":{"sourceLabel":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"6112792b-7b91-51dc-836e-f6968e1e2841","text":"Anode","isCorrect":false,"position":0},{"id":"4c3d606b-d06b-544d-ab1b-243ba2195725","text":"Salt bridge","isCorrect":false,"position":1},{"id":"cf270bdc-4020-5257-974d-4e9e53b3c8fe","text":"Both electrodes are always negative","isCorrect":false,"position":2},{"id":"b490ce26-22c2-5016-939a-e218de2728eb","text":"Cathode","isCorrect":true,"position":3}]},{"id":"1cf87aa1-bf51-5b1b-a581-cb95d8a9e847","position":238,"prompt":"How much charge passes when a current of 2.0 A flows for 30 minutes?","explanation":"Q = It = 2.0 × (30 × 60) = 3600 C.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Redox Reactions and Electrochemistry","fingerprint":"17761e9bd6c61fbac8087a2cf2707c964419733ab21c937d8965a0eeb6c959e9","studyRef":{"sourceLabel":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"23827cd3-eea7-5ac3-b66b-86e6bef9a578","text":"900 C","isCorrect":false,"position":0},{"id":"2946bc84-7dda-5c62-8e3f-5a0c35e54ae1","text":"7200 C","isCorrect":false,"position":1},{"id":"136e315e-30f9-5530-a62b-6a51836afd5c","text":"3600 C","isCorrect":true,"position":2},{"id":"b897b742-24f5-5039-93ef-af84cafc69f9","text":"60 C","isCorrect":false,"position":3}]},{"id":"bef4bc55-a479-5238-ab1e-a9aca1f196ff","position":239,"prompt":"How many moles of Cu are deposited by 193,000 C in Cu²⁺ + 2e⁻ → Cu, using F = 96,500 C mol⁻¹?","explanation":"193,000 C is 2.00 mol electrons, and two electron moles deposit one mole Cu.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Redox Reactions and Electrochemistry","fingerprint":"95b7a3f7ee21c981412538744139f46eef846e73162302e08f28c94d68ad3339","studyRef":{"sourceLabel":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","sourceKind":"general_chm101","reviewedFromLocalFiles":false},"generationMeta":{"import":"codex_chm101_240_v1","sourceReference":"General CHM 101 enrichment: Redox Reactions and Electrochemistry","calculationAndConceptCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a2150cd3-e555-57b1-bda0-d2cc380d0f7f","text":"4.00 mol","isCorrect":false,"position":0},{"id":"d8bde4af-a90d-5de7-985c-96bb7398c20b","text":"1.00 mol","isCorrect":true,"position":1},{"id":"6e306720-68f4-5d5c-8254-568331ca7f38","text":"0.50 mol","isCorrect":false,"position":2},{"id":"e3fc99e2-708d-5bb1-9176-ec45a0fcd53f","text":"2.00 mol","isCorrect":false,"position":3}]}]$chm101_questions$::jsonb)
  LOOP
    INSERT INTO public.study_quiz_questions
      (id, set_id, prompt, explanation, question_type, position, question_kind,
       difficulty_level, cognitive_level, source_topic, question_fingerprint,
       study_ref, generation_meta, ai_generated, published, created_at)
    VALUES
      ((v_question->>'id')::uuid, v_set_id, v_question->>'prompt', v_question->>'explanation',
       'mcq', (v_question->>'position')::integer, v_question->>'questionKind',
       v_question->>'difficulty', v_question->>'cognitive', v_question->>'topic',
       v_question->>'fingerprint', v_question->'studyRef', v_question->'generationMeta',
       false, true, now());

    FOR v_option IN
      SELECT value FROM jsonb_array_elements(v_question->'options')
    LOOP
      INSERT INTO public.study_quiz_options
        (id, question_id, text, is_correct, position, created_at)
      VALUES
        ((v_option->>'id')::uuid, (v_question->>'id')::uuid, v_option->>'text',
         (v_option->>'isCorrect')::boolean, (v_option->>'position')::integer, now());
    END LOOP;
  END LOOP;

  UPDATE public.study_quiz_sets
  SET questions_count = 240,
      exam_question_count = 40,
      time_limit_minutes = 40,
      published = false,
      visibility = 'private',
      updated_at = now()
  WHERE id = v_set_id;
END
$import$;

COMMIT;

-- Expected: 240 questions, 960 options, 240 correct options, 0 verified before admin review.
SELECT
  s.id AS set_id,
  s.title,
  count(DISTINCT q.id) AS questions,
  count(o.id) AS options,
  count(o.id) FILTER (WHERE o.is_correct) AS correct_options,
  count(DISTINCT q.id) FILTER (WHERE q.exam_verified_at IS NOT NULL) AS verified_questions
FROM public.study_quiz_sets s
LEFT JOIN public.study_quiz_questions q ON coalesce(q.set_id, q.quiz_set_id) = s.id
LEFT JOIN public.study_quiz_options o ON o.question_id = q.id
WHERE upper(regexp_replace(coalesce(s.course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'CHM101'
  AND s.delivery_mode = 'mock_exam'
  AND s.exam_campaign_key = 'supplementary-2026'
GROUP BY s.id, s.title;
